<?php namespace App\Http\Controllers; use App\Models\EducationalBonusSource; use App\Models\Scholarship; use App\Models\TestOffer; use Illuminate\Http\Request;
class EducationalServiceController extends Controller { private function model(string $type){return $type==='scholarships'?Scholarship::class:TestOffer::class;} public function index(string $type){return response()->json(['success'=>true,'data'=>$this->model($type)::query()->latest()->get()]);} public function store(Request $r,string $type){$d=$r->validate(['customer_id'=>'required|exists:customers,id','applicant_id'=>'nullable|exists:applicants,id','employee_id'=>'required|exists:employees,id','currency_id'=>'required|exists:currencies,id','package_type_id'=>'nullable|exists:package_types,id','date'=>'required|date','fee'=>'required|numeric|min:0','status'=>'sometimes|string']);$record=$this->model($type)::create($d);EducationalBonusSource::create(['employee_id'=>$d['employee_id'],'customer_id'=>$d['customer_id'],'applicant_id'=>$d['applicant_id']??null,'source_type'=>$record::class,'source_id'=>$record->id,'source_amount'=>$d['fee'],'bonus_amount'=>0,'status'=>'pending','rule_source'=>'manual_rule_pending']);return response()->json(['success'=>true,'data'=>$record],201);} }
